contracts/Greeter.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.0;

contract Greeter {
    string private greeting;

    event GreetingSet(string greeting);

    constructor(string memory _greeting) {
        greeting = _greeting;

        emit GreetingSet(_greeting);
    }

    function greet() public view returns (string memory) {
        return greeting;
    }

    function setGreeting(string memory _greeting) public {
        greeting = _greeting;

        emit GreetingSet(_greeting);
    }
}

contracts/mocks/SystemContractMocks.sol.content:
import "@hashgraph/smart-contracts/contracts/libraries/Constants.sol";

import "@hashgraph/smart-contracts/test/foundry/mocks/hts-precompile/HtsSystemContractMock.sol";
import "@hashgraph/smart-contracts/test/foundry/mocks/hts-precompile/HederaFungibleToken.sol";
import "@hashgraph/smart-contracts/test/foundry/mocks/exchange-rate-precompile/ExchangeRatePrecompileMock.sol";

contract ProxyToHtsMock is Constants {

    HtsSystemContractMock htsPrecompile = HtsSystemContractMock(HTS_PRECOMPILE);

    function createTokenForSender() external {

        address sender = address(this);
        string memory name = 'Token A';
        string memory symbol = 'TA';
        address treasury = sender;
        int64 initialTotalSupply = 1e16;
        int32 decimals = 8;

        _doCreateHederaFungibleTokenViaHtsPrecompile(sender, name, symbol, treasury, initialTotalSupply, decimals);

    }

    function sweepToSender(address token) external {
        uint256 balance = HederaFungibleToken(token).balanceOf(address(this));
        HederaFungibleToken(token).transfer(msg.sender, balance);
    }

    function _doCreateHederaFungibleTokenViaHtsPrecompile(
        address sender,
        string memory name,
        string memory symbol,
        address treasury,
        int64 initialTotalSupply,
        int32 decimals
    ) internal returns (address tokenAddress) {
        bool isToken;
        IHederaTokenService.HederaToken memory token = _getSimpleHederaToken(name, symbol, treasury);

        (, isToken) = htsPrecompile.isToken(tokenAddress);

        int64 responseCode;
        (responseCode, tokenAddress) = htsPrecompile.createFungibleToken(token, initialTotalSupply, decimals);

        int32 tokenType;
        (, isToken) = htsPrecompile.isToken(tokenAddress);

        (responseCode, tokenType) = htsPrecompile.getTokenType(tokenAddress);
    }

    function _getSimpleHederaToken(
        string memory name,
        string memory symbol,
        address treasury
    ) internal returns (IHederaTokenService.HederaToken memory token) {
        token.name = name;
        token.symbol = symbol;
        token.treasury = treasury;
    }

}

contracts/SimpleVault.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.0;
pragma experimental ABIEncoderV2;

import "@hashgraph/smart-contracts/contracts/safe-hts-precompile/SafeHTS.sol";

import "@hashgraph/smart-contracts/contracts/exchange-rate-precompile/SelfFunding.sol";

contract SimpleVault is SelfFunding, SafeHTS {

    // the hedera json rpc relay is set up such that 1e18 is 1 HBAR however 1 HBAR = 1e8 tinybar
    // so multiply by 1e10 to get the value in a format that the relay expects
    uint256 constant VALUE_MULTIPLIER = 1e10;

    mapping(address => bool) public isAssociated;
    mapping(address => mapping(address => uint64)) public vaultBalances;

    function associate(address token) external {
        if (!isAssociated[token]) {
            SafeHTS.safeAssociateToken(token, address(this));
            isAssociated[token] = true;
        }
    }

    function depositAndWithdraw(address depositToken, uint64 depositAmount, address withdrawToken, uint64 withdrawAmount) public payable costsCents(3) {
        deposit(depositToken, depositAmount);
        withdraw(withdrawToken, withdrawAmount);
    }

    function deposit(address token, uint64 amount) public payable costsCents(2) {
        SafeHTS.safeTransferToken(token, msg.sender, address(this), int64(amount));
        vaultBalances[token][msg.sender] += amount;
    }

    function withdraw(address token, uint64 amount) public payable costsCents(1) {
        SafeHTS.safeTransferToken(token, address(this), msg.sender, int64(amount));
        vaultBalances[token][msg.sender] -= amount;
    }

    function getCentsInTinybar(uint256 cents) external returns (uint256 tinybar) {
        uint256 tinycents = cents * TINY_PARTS_PER_WHOLE;
        tinybar = tinycentsToTinybars(tinycents) * VALUE_MULTIPLIER;
    }
}

